function applyRules(state){
  // state: {X1,X2,X3,X4} values in {T,F,U}
  // R1
  if(state.X1==="T" && state.X2==="T") state.X3="T";
  // R2
  if(state.X4==="F") state.X1="F";
  // R3
  if(state.X3==="F") {
    if(state.X2!=="F" && state.X4!=="F") { /* no change */ }
  }
  // R4
  if(state.X1==="U" || state.X2==="U") state.X4="U";
  return state;
}
```

